import{generateOrigin,SETTINGS}from './backgrounds.js';
// Birth contexts, resource scores and transition rates are authored game assumptions.
// They are not country population statistics or individual clinical predictions.
export function mix(seed,salt=0){if(typeof seed==='string'){let h=2166136261;for(const c of seed)h=Math.imul(h^c.charCodeAt(0),16777619);seed=h>>>0;}let x=(seed^Math.imul(salt+1,0x9e3779b1))>>>0;x=Math.imul(x^(x>>>16),0x7feb352d);x=Math.imul(x^(x>>>15),0x846ca68b);return(x^(x>>>16))>>>0}
export function initWorld(s){if(s.worldModel)return;const origin=generateOrigin(s,mix);s.worldModel={version:1,bornMonth:1+mix(s.seed,18)%12,origin:{...origin},litter:origin.mother?1+mix(s.seed,19)%7:mix(s.seed,19)%3,traits:{curiosity:15+mix(s.seed,20)%76,sensitivity:15+mix(s.seed,21)%76,sociability:15+mix(s.seed,22)%76,energy:15+mix(s.seed,23)%76},exposures:{people:origin.mother?0:10,noise:0},context:{...origin},contextArea:s.areaId,resource:origin.food,care:origin.support,seen:{},calendar:{ambient:s.day+12+mix(s.seed,24)%15,weather:s.day+15+mix(s.seed,25)%36,weatherUntil:0,contact:s.day+85+mix(s.seed,26)%65,friend:s.day+95+mix(s.seed,27)%85,household:s.day+180+mix(s.seed,28)%240},growth:{nursing:3+mix(s.seed,30)%4,mother:8+mix(s.seed,31)%4,play:27+mix(s.seed,32)%7,food:35+mix(s.seed,33)%7,recognize:65+mix(s.seed,34)%18,body:110+mix(s.seed,35)%40},history:[]};if(s.day===0){s.milestones={eyes:13+mix(s.seed,36)%7,walking:20+mix(s.seed,37)%6,weaning:46+mix(s.seed,38)%9};s.trust=Math.round(15+origin.support*.3);s.comfort=Math.round(35+origin.food*.4);s.temperament=s.worldModel.traits.sensitivity>65?'소리에 예민하고 신중한':s.worldModel.traits.energy>65?'활동량이 많고 활발한':s.worldModel.traits.sociability>65?'함께 지내기를 좋아하는':'자기 속도로 탐색하는';}}
export function syncContext(s){initWorld(s);const w=s.worldModel;if(w.contextArea===s.areaId)return;w.history.push({day:s.day,area:w.contextArea,context:w.context.id});w.context=generateOrigin(s,mix,s.areaSerial+50);w.contextArea=s.areaId;w.resource=w.context.food;w.care=w.context.support;}
export function environmentAllows(s,id){initWorld(s);if(s.day<90&&['street','street-bed','market-smell','meal-search','territory','bird','grass','puddle'].includes(id))return false;if(s.day<35&&id!=='sleep')return false;const c=s.worldModel.context;if(['child-home','new-pet','beach'].includes(id)&&s.worldModel.care<60)return false;if(['puzzle','fetch','tug','scent-game','rainy-play'].includes(id)&&s.worldModel.resource<45)return false;if(['market-smell','street'].includes(id)&&c.space!=='market')return false;if(['beach','dig-sand','habit-sand'].includes(id)&&!['garden','village'].includes(c.space))return false;if(id==='new-pet'&&c.space==='indoor'&&s.worldModel.care<50)return false;if(['boarding','car-ride'].includes(id)&&s.worldModel.care<40)return false;return true;}
export function eventWeight(s,e){const w=s.worldModel,t=w.traits;let score=1;if(['play','exploration'].includes(e.cat))score*=.4+t.energy/50;if(e.cat==='learning')score*=.4+t.curiosity/50;if(e.cat==='fear')score*=.3+t.sensitivity/40;if(['family','separation'].includes(e.cat))score*=.4+t.sociability/50;if(e.cat==='food'||e.cat==='survival')score*=.5+(100-w.resource)/35;if(e.cat==='care')score*=.4+w.care/65;if(s.stress>65&&['exploration','play'].includes(e.cat))score*=.3;return score;}
export function weightedEvent(s,pool,random){const weights=pool.map(e=>eventWeight(s,e)),total=weights.reduce((a,b)=>a+b,0);let r=random(s)*total;for(let i=0;i<pool.length;i++){r-=weights[i];if(r<=0)return pool[i]}return pool.at(-1)}
export function birthText(s){const w=s.worldModel;return `${s.country.name} · ${w.origin.label}. ${w.origin.story} ${w.origin.mother?(w.litter>1?`나를 포함해 ${w.litter}마리의 작은 몸이 모여 있다.`:'곁에 다른 새끼는 없다.'):(w.litter?'나 말고도 돌봄을 받는 작은 몸들이 있다.':'이 자리에서는 나 혼자 돌봄을 받는다.')}`;}
export function initDevelopment(s){if(s.development)return;const w=s.worldModel,g=w.growth,m=s.milestones,due={newborn:1,nursing:g.nursing,mother:g.mother,eyes:m.eyes,ears:m.ears,walking:m.walking,'litter-play':g.play,'first-food':g.food,weaning:m.weaning,recognize:g.recognize,'growing-body':g.body};s.development={version:1,historicalUnknown:s.day?Object.keys(due).filter(id=>due[id]<s.day&&!s.memories.includes(id)):[]};}
export function contextualGrowth(s,log,remember){initWorld(s);const w=s.worldModel,g=w.growth,o=w.origin,d=s.day;initDevelopment(s);let id,text;const emit=()=>{if(!id||s.memories.includes(id)||s.development.historicalUnknown.includes(id))return;if(['walking','litter-play','growing-body'].includes(id)&&s.medical?.episode)return;log(s,id,text);remember(s,id);if(['eyes','walking','weaning','litter-play'].includes(id))s.log.at(-1).source='merck-development';};if(d>=1){id='newborn';text=o.mother?(w.litter>1?'눈도 귀도 아직 세상에 열리지 않았다. 다른 새끼 사이로 몸을 밀어 어미의 온기에 닿는다.':'아직 몸을 일으킬 수 없다. 어미의 배 가까이에서 작은 앞발을 움직인다.'):'몸을 일으키지 못한 채 따뜻한 천에 기대 있다. 나를 받치는 손이 조심스럽게 자세를 바꿔 준다.';emit();id=null;}
if(d>=g.nursing){id='nursing';text=o.mother?(w.litter>3?'젖을 찾는 형제들 사이에서 몸을 밀어 넣는다. 어미가 자세를 바꾸자 가까운 자리를 차지한다.':'어미 곁에서 젖을 먹다가 잠든다. 어미의 호흡이 몸을 천천히 흔든다.'):'사람의 손에 받쳐 먹이를 받아먹는다. 먹고 난 뒤에는 따뜻한 자리에서 다시 잠든다.';emit();id=null;}
if(d>=g.mother){id='mother';text=o.mother?(o.sound>60?'밖의 큰 소리에 어미가 움직인다. 내 몸은 어미 배 아래쪽으로 더 파고든다.':'어미가 배와 등을 핥는다. 몸의 긴장이 풀려 그대로 잠든다.'):'어미의 혀 대신 부드러운 천과 손이 몸을 돌본다. 돌봄 시간마다 비슷한 손길이 돌아온다.';emit();id=null;}
if(d>=s.milestones.eyes){id='eyes';text=o.space==='rural'?'둥지 입구의 빛이 흐릿한 얼룩으로 보인다. 어미의 몸 너머로 밝고 어두운 자리를 구분한다.':o.mother?'어미의 몸이 전보다 큰 그림자로 보인다. 눈꺼풀 사이로 빛이 들어오지만 아직 선명하지 않다.':'눈꺼풀 사이로 천과 사람 손의 윤곽이 흐릿하게 들어온다. 처음 보는 빛에 눈을 가늘게 뜬다.';emit();id=null;}
if(d>=s.milestones.walking){id='walking';text=o.space==='rural'?'둥지 안의 울퉁불퉁한 바닥에서 앞발을 세운다. 몇 걸음 떼다 주저앉고 어미 곁에서 다시 버텨 본다.':o.mother?'깔린 천 위에서 몸을 든다. 발이 벌어져 주저앉았다가, 어미 곁을 향해 다시 짧게 걸어 본다.':'미끄럽지 않게 깔린 천을 앞발로 짚는다. 몇 걸음 뒤 주저앉자 사람은 일으켜 세우지 않고 지켜본다.';emit();id=null;}
if(d>=g.play){id='litter-play';text=w.litter>1&&o.mother?'형제 하나가 내 앞발을 건드린다. 밀고 밀리며 몸의 힘을 맞춰 본다.':o.mother?'곁에 형제는 없다. 누워 있는 어미의 발과 마른 잎을 번갈아 건드린다.':'돌보는 사람이 바닥에 작은 천을 놓았다. 아직 서툰 발로 건드리며 짧게 움직인다.';emit();id=null;}
if(d>=g.food){id='first-food';text=o.home==='street'?'둥지 가까이에 놓인 부드러운 먹이를 핥아 본다. 아직 혼자 멀리 먹이를 찾으러 나가지 않는다.':'낮은 그릇에 젖과 다른 먹이가 조금 놓였다. 입 주위에 묻히며 천천히 핥아 본다.';emit();id=null;}
if(d>=s.milestones.weaning){id='weaning';text=o.mother?'젖을 찾는 시간이 줄고 그릇에서 먹는 시간이 늘었다. 쉬고 먹는 범위는 아직 둥지 주변이다.':'사람에게 받아먹는 방식에서 낮은 그릇을 쓰는 방식으로 조금씩 옮겨 간다. 내 속도에 맞춰 먹는다.';emit();id=null;}
if(d>=g.recognize){id='recognize';text=o.mother&&o.home==='street'?'어미가 돌아오는 기척에 고개를 든다. 둥지 주변의 낯선 움직임과 익숙한 움직임이 구분되기 시작한다.':w.traits.sensitivity>65?'작은 소리에도 멈춰 서는 편이다. 익숙한 손길 앞에서는 몸의 힘이 조금 풀린다.':'자주 오는 발소리를 구별한다. 그 소리가 나면 고개를 들고 몸을 일으킨다.';emit();id=null;}
if(d>=g.body){id='growing-body';text=w.traits.energy>65?'몸이 커지자 짧게 뛰는 시간이 늘었다. 한바탕 움직인 뒤에는 곯아떨어져 잔다.':'전에 주저앉던 턱 앞에서 발을 옮겨 본다. 나만의 속도로 몸을 쓰는 범위가 넓어진다.'}
emit();}
export function worldStep(s,{log,random,clamp}){syncContext(s);const w=s.worldModel,c=w.calendar;if(s.day%7===0){const support=s.story.care==='reduced'?w.care*.6:w.care;const strain=(100-w.resource)/100+(100-support)/100;s.stress=clamp(s.stress+(strain>.95?1:-.4));s.comfort=clamp(s.comfort+(support>65?.25:support<30?-.3:0));if(s.day>90&&w.resource<30)s.health=clamp(s.health-.08);}
if(s.day>=c.weather){const month=1+((w.bornMonth-1+Math.floor(s.day/30))%12),summer=month>=6&&month<=8,winter=month<=2||month===12;const pool=s.country.climate==='hot'?['quiet','quiet','heat','rain']:winter?['quiet','cold','rain']:summer?['quiet','heat','rain']:['quiet','quiet','rain'];s.world=pool[Math.floor(random(s)*pool.length)];c.weatherUntil=s.day+2+Math.floor(random(s)*7);c.weather=s.day+15+Math.floor(random(s)*32);if(s.world!=='quiet'){const t={rain:w.context.space==='market'?'가게 뒤 둥지 밖으로 빗물이 흘러간다. 지붕 아래 마른 쪽으로 몸을 모은다.':'창과 지붕에 빗방울이 부딪힌다. 바깥 활동이 줄고 마른 자리를 더 오래 쓴다.',heat:s.home==='family'?'낮의 더위 때문에 사람이 활동 시간을 늦췄다. 물과 그늘 가까이에서 쉰다.':'낮의 더위를 피해 그늘과 물 있는 곳에서 움직임을 줄인다.',cold:s.home==='family'?'바깥 공기가 차다. 바닥에 깔린 자리가 더 두꺼워졌다.':'바깥 공기가 차다. 바람이 덜 드는 잠자리가 중요해졌다.'};if(s.day<30)log(s,'world',s.world==='rain'?'잠자리 바깥에서 비 소리가 난다. 작은 몸은 돌봄이 있는 안쪽에 머문다.':s.world==='cold'?'잠자리 밖의 공기가 차다. 아직 혼자 체온을 지킬 수 없어 돌봄과 온기에 의지한다.':'바깥 공기가 더워졌다. 돌보는 존재가 있는 자리에서 몸을 쉬게 한다.');else log(s,'world',t[s.world]);s.comfort=clamp(s.comfort-(s.home==='family'?1:3));}}
if(s.day>c.weatherUntil)s.world='quiet';
if(s.day>=c.household){c.household=s.day+240+Math.floor(random(s)*350);if(s.day<180||s.story.lost)return;const r=random(s);if(s.home==='family'){if(r<.35){w.care=Math.max(15,w.care-20);s.story.care='reduced';s.story.careUntil=s.day+20+Math.floor(random(s)*45);log(s,'household-work','사람의 생활 시간이 달라졌다. 혼자 쉬는 시간이 늘고 놀이가 짧아졌다. 익숙한 일정이 잠시 흔들린다.')}else{w.care=Math.min(95,w.care+12);log(s,'household-support','가족 중 한 사람이 내 돌봄을 더 나누어 맡는다. 정해진 시간에 밥과 휴식이 이어진다.')}}else if(r<.5){w.resource=Math.max(10,w.resource-18);log(s,'resource-change',s.home==='street'?'먹이를 찾던 자리가 닫히고 주변 길이 바뀌었다. 예전 이동 경로를 그대로 쓸 수 없게 됐다.':'돌보는 사람들의 손이 분주하다. 같은 공간에서 기다리는 시간이 길어졌다.')}else{w.resource=Math.min(95,w.resource+15);log(s,'resource-support',s.home==='street'?'이웃 한 사람이 물과 먹이를 놓는 자리를 마련했다. 찾아갈 수 있는 자리가 하나 늘었다.':'돌보는 손이 늘었다. 공간을 정리하고 쉬는 시간을 나누어 주는 사람이 생겼다.')}}}
export function adaptToChoice(s,p,id){initWorld(s);const w=s.worldModel;if(p.id.startsWith('life:')){if(['turn','away','retreat','pause','rest','den'].includes(id)){w.traits.sensitivity=Math.max(5,w.traits.sensitivity-1);w.exposures.noise++}if(['return','roll','steady','search','nose','trade'].includes(id))w.traits.curiosity=Math.min(95,w.traits.curiosity+2);if(['adult','person','help','near'].includes(id))w.traits.sociability=Math.min(95,w.traits.sociability+2);}if(p.id==='encounter')w.exposures.people++;}
